/**
 * Capture a folder's boards as the starter template every new account gets.
 *
 * The template is not generated by a seed script that rebuilds the boards from
 * code — it is a *copy of the real thing*, taken from a workspace where the
 * boards have been written, laid out and edited by hand. That is the point: a
 * new person should open the same boards you would show them, not a
 * reconstruction that drifts from them every time either side is edited.
 *
 * Run it whenever the docs boards change:
 *
 *   node scripts/make-template.mjs                       # from ./data, folder "Cartographer Docs"
 *   node scripts/make-template.mjs --folder "Guides"     # a different folder
 *   DATA_DIR=/tmp/other node scripts/make-template.mjs   # a different volume
 *
 * It reads the volume directly rather than the API, because it needs the files
 * exactly as they are on disk — that is what will be copied into a new account.
 */
import { cp, mkdir, readdir, readFile, rm, stat, writeFile } from 'node:fs/promises';
import path from 'node:path';

const DATA_DIR = process.env.DATA_DIR ?? './data';
const OUT = process.env.TEMPLATE_DIR ?? './templates/starter';
const wanted = process.argv.includes('--folder')
  ? process.argv[process.argv.indexOf('--folder') + 1]
  : 'Cartographer Docs';

const readJson = async (file) => {
  try {
    return JSON.parse(await readFile(file, 'utf8'));
  } catch {
    return null;
  }
};

const users = await readdir(path.join(DATA_DIR, 'users')).catch(() => []);
if (!users.length) {
  console.error(`No workspaces under ${DATA_DIR}/users — is DATA_DIR right?`);
  process.exit(2);
}

/*
 * Search every workspace rather than assuming the first. On a multi-user volume
 * the docs may live in any of them, and picking wrong would silently ship an
 * empty template.
 */
let found = null;
for (const user of users) {
  const root = path.join(DATA_DIR, 'users', user);
  const file = await readJson(path.join(root, 'folders.json'));
  const folder = file?.folders?.find((f) => f.name === wanted);
  if (folder) found = { root, file, folder };
}
if (!found) {
  console.error(`No folder called "${wanted}" in any workspace under ${DATA_DIR}.`);
  process.exit(2);
}

const { root, file, folder } = found;
const boardsDir = path.join(root, 'boards');
const live = {};
for (const id of await readdir(boardsDir).catch(() => [])) {
  const board = await readJson(path.join(boardsDir, id, 'board.json'));
  if (board) live[id] = board;
}

// Assignments name roots; sub-boards come along because a root is useless
// without the boards its cards drill into.
const roots = Object.entries(file.assignments)
  .filter(([id, fid]) => fid === folder.id && live[id])
  .map(([id]) => id);

const include = new Set();
const descend = (id) => {
  if (include.has(id) || !live[id]) return;
  include.add(id);
  for (const node of live[id].nodes ?? []) {
    for (const child of node.childBoards ?? []) descend(child);
  }
};
roots.forEach(descend);

if (!include.size) {
  console.error(`"${wanted}" has no live boards — nothing to capture.`);
  process.exit(2);
}

await rm(OUT, { recursive: true, force: true });
await mkdir(path.join(OUT, 'boards'), { recursive: true });

let bytes = 0;
for (const id of include) {
  const from = path.join(boardsDir, id);
  await cp(from, path.join(OUT, 'boards', id), { recursive: true });
  const walk = async (dir) => {
    for (const entry of await readdir(dir, { withFileTypes: true })) {
      const p = path.join(dir, entry.name);
      if (entry.isDirectory()) await walk(p);
      else bytes += (await stat(p)).size;
    }
  };
  await walk(from);
}

await writeFile(
  path.join(OUT, 'manifest.json'),
  `${JSON.stringify(
    {
      folder: { name: folder.name, ...(folder.color ? { color: folder.color } : {}) },
      // Only roots are filed. Sub-boards are reached by drilling in, and filing
      // them separately would list them twice on the Folders tab.
      roots,
      boards: [...include],
    },
    null,
    2,
  )}\n`,
);

console.log(`Captured "${folder.name}" → ${OUT}`);
for (const id of include) {
  console.log(`  ${roots.includes(id) ? '•' : '  ↳'} ${live[id].name} (${live[id].nodes?.length ?? 0} nodes)`);
}
console.log(`  ${include.size} boards, ${Math.round(bytes / 1024)}KB`);
